"""Real JBD2 transactions generated by debugfs on explicitly disposable images."""
import hashlib,shutil,struct,subprocess
from pathlib import Path

def run(argv):return subprocess.check_output(list(map(str,argv)),stderr=subprocess.PIPE,timeout=90)
def debug(image,command):return run(['debugfs','-w','-R',command,image])
def sha(path):
 with Path(path).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()

def create(source,image,*,version=3,kind='committed',unclean=True):
 image=Path(image);shutil.copyfile(source,image)
 with image.open('rb') as f:f.seek(1024);sb=f.read(1024)
 block=1024<<struct.unpack_from('<I',sb,24)[0]
 numbers=list(map(int,debug(image,'blocks /existing-file').split()));number=numbers[0]
 original=run(['debugfs','-R','cat /existing-file',image]);payload=image.with_suffix('.payload')
 data=(b'native journal replay\n'+bytes(range(251))*(block//251+1))[:block]
 # Exercise JBD2 escaped payload handling: the replayed block starts with magic.
 if kind=='escaped':data=struct.pack('>I',0xc03b3998)+data[4:]
 payload.write_bytes(data)
 # debugfs v1 checksum generation for revoke-only transactions is invalid.
 # Exercise legacy revokes without checksums; metadata_csum profiles use v2/3.
 has_csum=bool(struct.unpack_from('<I',sb,100)[0]&0x400)
 commands=[f'journal_open -c -v {version}' if kind!='revoke' or has_csum else 'journal_open']
 if kind=='uncommitted':
  seed=image.with_suffix('.seedpayload');seed.write_bytes(original[block:2*block]);commands.append(f'journal_write -b {numbers[1]} {seed}')
 commands.append(f'journal_write {"-c " if kind=="uncommitted" else ""}-b {number} {payload}')
 if kind=='revoke':commands.append(f'journal_write -r {number} {payload}')
 if kind=='tail':
  tail=image.with_suffix('.tailpayload');tail.write_bytes(b'UNCOMMITTED'+data[11:]);commands.append(f'journal_write -c -b {number} {tail}')
 features=struct.unpack_from('<I',sb,96)[0]
 commands+=['journal_close',f'set_super_value feature_incompat {features|4}',f'set_super_value state {0 if unclean else 1}']
 script=image.with_suffix('.commands');script.write_text('\n'.join(commands)+'\n')
 output=run(['debugfs','-w','-f',script,image])
 # debugfs can exit zero despite command errors, so inspect the actual log.
 dump=run(['debugfs','-R','logdump -S',image])
 if b'Journal start:            1' not in dump:raise AssertionError((output,dump))
 expected=original if kind in ('uncommitted','revoke') else data+original[block:]
 return dict(block=block,number=number,old=original,new=expected,log=dump)
